<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import CommandCenter from './views/CommandCenter.vue'
import OperationsConsole from './views/OperationsConsole.vue'
import SettingsView from './views/SettingsView.vue'
import AuthPanel from './components/AuthPanel.vue'
import AppTutorial from './components/AppTutorial.vue'
import { api, getAuthToken, logout } from './services/api.js'
import logoUrl from './assets/logisphere-logo.png'

const isAuthenticated = ref(!!getAuthToken())
const activeWorkspace = ref('shipments')
const operationsTab = ref('orders')
const commandTab = ref('tracking')
const sidebarOpen = ref(true)
const isMobile = ref(false)
const profileMenuOpen = ref(false)
const searchQuery = ref('')
const pendingApprovalsCount = ref(0)
const currentUser = ref(JSON.parse(localStorage.getItem('ls_user') || 'null'))
const theme = ref(localStorage.getItem('ls_theme') || 'figma')
const showTutorial = ref(!!getAuthToken() && !localStorage.getItem('ls_tutorial_complete'))
const pageTitle = computed(() => activeWorkspace.value === 'settings' ? 'Settings' : activeWorkspace.value === 'shipments' ? ({ tracking: 'Command Center', shipments: 'Shipments', risk: 'Alerts & Exceptions', recommendations: 'Approvals', communications: 'Customer Updates' }[commandTab] || 'Command Center') : ({ orders: 'Orders & Dispatch', planning: 'Load Planning', inventory: 'Warehouse', delivery: 'Delivery & ePOD', analytics: 'Analytics & Reports', returns: 'Returns', assistant: 'Copilot Assistant', alerts: 'Activity Log', rules: 'System Rules' }[operationsTab] || 'Operations'))
function handleAuthenticated() { currentUser.value = JSON.parse(localStorage.getItem('ls_user') || 'null'); isAuthenticated.value = true; showTutorial.value = !localStorage.getItem('ls_tutorial_complete') }
function handleLogout() { logout(); profileMenuOpen.value = false; isAuthenticated.value = false }
function handleAuthExpired() { profileMenuOpen.value = false; currentUser.value = null; isAuthenticated.value = false }
function setWorkspace(workspace, tab) { activeWorkspace.value = workspace; profileMenuOpen.value = false; if (tab) operationsTab.value = tab; if (isMobile.value) sidebarOpen.value = false }
function setCommandWorkspace(tab = 'tracking') { activeWorkspace.value = 'shipments'; commandTab.value = tab; profileMenuOpen.value = false; if (isMobile.value) sidebarOpen.value = false }
function openSettings() { setWorkspace('settings') }
function navigateTutorial(target) { activeWorkspace.value = target === 'Operations' ? 'operations' : 'shipments' }
function setTheme(nextTheme) { theme.value = nextTheme; localStorage.setItem('ls_theme', nextTheme) }
function handleAccountDeleted() { logout(); isAuthenticated.value = false; activeWorkspace.value = 'shipments' }
function handleProfileUpdated(user) { currentUser.value = user; localStorage.setItem('ls_user', JSON.stringify(user)); profileMenuOpen.value = false }
async function hydrateProfile() { if (!isAuthenticated.value) return; try { handleProfileUpdated((await api.getProfile()).user) } catch { /* expired sessions are handled by the next protected request */ } }
function syncViewport() { const mobile = window.matchMedia('(max-width: 800px)').matches; if (mobile && !isMobile.value) sidebarOpen.value = false; isMobile.value = mobile }
onMounted(() => { hydrateProfile(); syncViewport(); window.addEventListener('resize', syncViewport); window.addEventListener('ls:auth-expired', handleAuthExpired) })
onBeforeUnmount(() => { window.removeEventListener('resize', syncViewport); window.removeEventListener('ls:auth-expired', handleAuthExpired) })
</script>

<template>
  <div class="app-shell" :class="{ 'sidebar-closed': !sidebarOpen, 'auth-shell': !isAuthenticated, 'mobile-view': isMobile }" :data-theme="theme">
    <template v-if="isAuthenticated">
      <aside class="sidebar" aria-label="Main navigation">
        <div class="sidebar-top"><div class="brand"><img :src="logoUrl" alt="LogiSphere" class="app-logo" /><span class="brand-name">LogiSphere</span></div><button class="collapse" :aria-label="sidebarOpen ? 'Collapse sidebar' : 'Expand sidebar'" @click="sidebarOpen = !sidebarOpen">{{ sidebarOpen ? '‹' : '›' }}</button></div>
        <nav class="nav-group"><span class="nav-label">WORKSPACE</span>
          <button :class="{ active: activeWorkspace === 'shipments' && commandTab === 'tracking' }" title="Command Center" @click="setCommandWorkspace('tracking')"><i>▥</i><span>Command Center</span></button>
          <button :class="{ active: activeWorkspace === 'shipments' && commandTab === 'shipments' }" title="Shipments" @click="setCommandWorkspace('shipments')"><i>▰</i><span>Shipments</span></button>
          <button :class="{ active: activeWorkspace === 'shipments' && commandTab === 'risk' }" title="Alerts & Exceptions" @click="setCommandWorkspace('risk')"><i>⚠</i><span>Alerts & Exceptions</span></button>
          <button :class="{ active: activeWorkspace === 'operations' && operationsTab === 'rules' }" title="System Rules" @click="setWorkspace('operations', 'rules')"><i>☷</i><span>System Rules</span></button>
          <button :class="{ active: activeWorkspace === 'operations' && operationsTab === 'assistant' }" title="Copilot Assistant" @click="setWorkspace('operations', 'assistant')"><i>▱</i><span>Copilot Assistant</span></button>
          <button :class="{ active: activeWorkspace === 'shipments' && commandTab === 'recommendations' }" title="Approvals" @click="setCommandWorkspace('recommendations')"><i>✓</i><span>Approvals</span></button>
          <button :class="{ active: activeWorkspace === 'shipments' && commandTab === 'communications' }" title="Customer updates" @click="setCommandWorkspace('communications')"><i>✉</i><span>Customer updates</span></button>
        </nav>
        <nav class="nav-group secondary"><span class="nav-label">OPERATIONS</span>
          <button :class="{ active: activeWorkspace === 'operations' && operationsTab === 'orders' }" title="Orders & Dispatch" @click="setWorkspace('operations', 'orders')"><i>▦</i><span>Orders & Dispatch</span></button>
          <button :class="{ active: activeWorkspace === 'operations' && operationsTab === 'planning' }" title="Load Planning" @click="setWorkspace('operations', 'planning')"><i>▣</i><span>Load Planning</span></button>
          <button :class="{ active: activeWorkspace === 'operations' && operationsTab === 'inventory' }" title="Warehouse" @click="setWorkspace('operations', 'inventory')"><i>⬡</i><span>Warehouse</span></button>
          <button :class="{ active: activeWorkspace === 'operations' && operationsTab === 'delivery' }" title="Delivery & ePOD" @click="setWorkspace('operations', 'delivery')"><i>↗</i><span>Delivery & ePOD</span></button>
          <button :class="{ active: activeWorkspace === 'operations' && operationsTab === 'analytics' }" title="Analytics & Reports" @click="setWorkspace('operations', 'analytics')"><i>▤</i><span>Analytics & Reports</span></button>
          <button :class="{ active: activeWorkspace === 'operations' && operationsTab === 'returns' }" title="Returns" @click="setWorkspace('operations', 'returns')"><i>↶</i><span>Returns</span></button>
          <button :class="{ active: activeWorkspace === 'operations' && operationsTab === 'alerts' }" title="Activity Log" @click="setWorkspace('operations', 'alerts')"><i>◷</i><span>Activity Log</span></button>
        </nav>
        <nav class="nav-group secondary"><span class="nav-label">CUSTOMER VIEW</span><button title="Public Live Tracking" @click="setCommandWorkspace('tracking')"><i>↗</i><span>Public Live Tracking</span></button></nav>
        <div class="sidebar-bottom"><div class="profile-wrap"><button type="button" class="profile" :aria-expanded="profileMenuOpen" @click="profileMenuOpen = !profileMenuOpen"><span class="avatar">{{ currentUser?.full_name?.slice(0, 2).toUpperCase() || 'LS' }}</span><span><strong>{{ currentUser?.full_name || 'Operations team' }}</strong><small>{{ currentUser?.role || 'Operations' }}</small></span><i>⌄</i></button><div v-if="profileMenuOpen" class="profile-menu"><button type="button" @click.stop="openSettings"><i>✎</i>Profile & settings</button><button type="button" @click="handleLogout"><i>↪</i>Sign out</button></div></div><button type="button" title="Settings" @click="openSettings"><i>⚙</i><span>Settings</span></button><button type="button" title="App Tutorial" @click="showTutorial = true"><i>?</i><span>App Tutorial</span></button></div>
      </aside>
      <button v-if="isMobile && sidebarOpen" class="nav-scrim" aria-label="Close navigation" @click="sidebarOpen = false"></button>
      <section class="workspace"><header class="topbar"><div class="topbar-title"><span class="breadcrumb">LogiSphere / {{ pageTitle }}</span><h1>{{ pageTitle }}</h1></div><div class="top-actions"><input v-model="searchQuery" class="global-search" aria-label="Search shipments and orders" placeholder="Search shipments, orders, or vehicles…" /><button class="approval-shortcut" @click="setCommandWorkspace('recommendations')">{{ pendingApprovalsCount }} Needs approval</button><div class="agent-status"><b></b><span>System online</span></div><button class="help" @click="showTutorial = true">Help</button></div></header><main class="content"><CommandCenter v-if="activeWorkspace === 'shipments'" :initial-tab="commandTab" :search-query="searchQuery" @pending-approvals="pendingApprovalsCount = $event" /><OperationsConsole v-else-if="activeWorkspace === 'operations'" :initial-tab="operationsTab" :search-query="searchQuery" /><SettingsView v-else :theme="theme" :user="currentUser" @update-theme="setTheme" @profile-updated="handleProfileUpdated" @account-deleted="handleAccountDeleted" /></main></section>
      <button v-if="!sidebarOpen && isMobile" class="open-sidebar" aria-label="Open sidebar" @click="sidebarOpen = true">›</button>
      <AppTutorial :open="showTutorial" @close="showTutorial = false" @navigate="navigateTutorial" />
    </template>
    <main v-else class="auth-layout"><AuthPanel @authenticated="handleAuthenticated" /></main>
  </div>
</template>

<style scoped>
.app-shell{min-height:100dvh;display:grid;grid-template-columns:264px minmax(0,1fr);background:var(--ink);transition:grid-template-columns .2s ease}.app-shell.auth-shell{display:block}.app-shell.sidebar-closed{grid-template-columns:76px minmax(0,1fr)}.sidebar{position:sticky;top:0;height:100dvh;display:flex;flex-direction:column;gap:.5rem;overflow-y:auto;overflow-x:hidden;padding:.8rem .85rem;background:var(--panel);border-right:1px solid var(--line);white-space:nowrap;z-index:21}.sidebar-closed .sidebar{padding:.8rem .55rem}.sidebar-closed .brand-name,.sidebar-closed .nav-label,.sidebar-closed .nav-group button span,.sidebar-closed .sidebar-bottom button span,.sidebar-closed .profile>span:nth-child(2),.sidebar-closed .profile>i{display:none}.sidebar-closed .sidebar-top{height:3.8rem;display:grid;grid-template-rows:2.35rem 1.2rem;justify-items:center;align-content:start;gap:.12rem;padding:.15rem 0 .35rem}.sidebar-closed .collapse{position:static;width:1.5rem;height:1.2rem;min-height:1.2rem;padding:0;background:transparent;z-index:1;font-size:1rem;line-height:1}.sidebar-closed .nav-group button,.sidebar-closed .sidebar-bottom button{justify-content:center;gap:0;width:2.55rem;height:2.55rem;min-height:2.55rem;margin:0 auto;padding:0;border-radius:9px}.sidebar-closed .nav-group i,.sidebar-closed .sidebar-bottom i{width:1.2rem;font-size:1.12rem}.sidebar-closed .profile-wrap{margin:0;padding-top:.35rem}.sidebar-closed .profile{justify-content:center!important}.sidebar-top{display:flex;align-items:center;justify-content:space-between;gap:.6rem;padding:.15rem .4rem .45rem}.brand{display:flex;align-items:center;gap:.65rem;color:var(--text);font-weight:750}.app-logo{width:2.35rem;height:2.35rem;border-radius:10px;object-fit:cover;object-position:center;background:#fff}.brand-name{font-size:1.02rem;letter-spacing:-.04em}.collapse{width:1.65rem;height:1.65rem;padding:0;border:0;background:transparent;color:var(--text-dim);font-size:1.3rem}.nav-group{display:flex;flex-direction:column;gap:.22rem}.nav-label{margin:.6rem .5rem .3rem;color:var(--text-dim);font:.68rem var(--font-body);font-weight:750;letter-spacing:.02em}.nav-group button,.sidebar-bottom button{display:flex;align-items:center;gap:.7rem;width:100%;min-height:2.45rem;border:0;background:transparent;color:var(--text-dim);text-align:left;padding:.48rem .7rem;border-radius:10px}.nav-group button:hover,.sidebar-bottom button:hover{background:var(--panel-2);border:0}.nav-group button.active{background:#2563eb;color:white;font-weight:650}.nav-group i,.sidebar-bottom i{display:grid;place-items:center;width:1rem;flex:none;font-style:normal;font-size:1.05rem}.secondary{border-top:1px solid var(--line);padding-top:.35rem}.sidebar-bottom{position:sticky;bottom:0;margin-top:auto;display:flex;flex-direction:column;gap:.1rem;padding-top:.5rem;background:var(--panel);flex-shrink:0}.profile-wrap{position:relative;margin:0 .3rem;padding-top:.5rem;border-top:1px solid var(--line)}.profile{justify-content:flex-start;padding:.35rem!important;color:var(--text-dim)!important;font-size:.75rem!important}.profile>span:nth-child(2){flex:1}.profile strong{display:block}.profile small{display:block;margin-top:.12rem;color:var(--text-dim)}.profile-menu{position:absolute;z-index:30;bottom:calc(100% + .5rem);left:0;right:0;padding:.3rem;background:var(--panel);border:1px solid var(--line);border-radius:9px;box-shadow:0 12px 28px rgba(20,48,76,.18)}.profile-menu button{padding:.5rem!important;color:var(--text)!important}.avatar{display:grid;place-items:center;width:1.8rem;height:1.8rem;border-radius:50%;background:var(--panel-2);color:var(--signal);font:.62rem var(--font-mono)}.workspace{min-width:0}.topbar{min-height:64px;display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:.85rem 1.4rem;background:var(--panel);border-bottom:1px solid var(--line)}.topbar-title{display:none}.topbar h1{color:var(--text);font-size:1.15rem}.top-actions{display:flex;align-items:center;gap:.65rem;flex:1}.global-search{width:min(560px,55vw);margin-right:auto}.approval-shortcut{white-space:nowrap;border:1px solid #fed7aa;background:#fff7ed;color:#c2410c;border-radius:999px;padding:.45rem .8rem;font-size:.75rem}.agent-status{display:flex;align-items:center;gap:.45rem;color:var(--text-dim);font-size:.75rem;white-space:nowrap}.agent-status b{width:.48rem;height:.48rem;border-radius:50%;background:#31a274;box-shadow:0 0 0 4px color-mix(in srgb,#31a274 17%,transparent)}.help{border-color:var(--line);background:var(--panel);color:var(--signal)}.content{width:min(100%,1600px);margin:0 auto;padding:22px clamp(16px,2vw,28px)}.open-sidebar{position:fixed;left:.8rem;top:1.15rem;z-index:24;display:grid;place-items:center;width:2rem;height:2rem;padding:0;border-radius:8px;background:var(--panel);color:var(--signal);border-color:var(--line);font-size:1.5rem}.nav-scrim{display:none}.auth-layout{min-height:100dvh;display:grid;place-items:center;padding:1.25rem;background:radial-gradient(circle at top left,color-mix(in srgb,var(--signal) 20%,transparent),transparent 40%),var(--ink)}@media(max-width:800px){.app-shell,.app-shell.sidebar-closed{grid-template-columns:1fr}.sidebar{position:fixed;left:0;top:0;width:min(280px,84vw);transform:translateX(-110%);transition:transform .2s ease;box-shadow:12px 0 30px rgba(0,0,0,.25)}.app-shell:not(.sidebar-closed) .sidebar{transform:translateX(0)}.sidebar-closed .sidebar{padding:.8rem .85rem}.sidebar-closed .brand-name,.sidebar-closed .nav-label,.sidebar-closed .nav-group button span,.sidebar-closed .sidebar-bottom button span,.sidebar-closed .profile>span:nth-child(2),.sidebar-closed .profile>i{display:initial}.sidebar-closed .sidebar-top{height:auto;display:flex;justify-content:space-between;padding:.15rem .4rem .45rem}.sidebar-closed .collapse{position:static;width:1.65rem;height:1.65rem;min-height:1.65rem;font-size:1.3rem}.sidebar-closed .nav-group button,.sidebar-closed .sidebar-bottom button{justify-content:flex-start;gap:.7rem;width:100%;height:auto;margin:0;padding:.48rem .7rem;min-height:2.55rem}.sidebar-closed .nav-group i,.sidebar-closed .sidebar-bottom i{width:1rem;font-size:1.05rem}.sidebar-closed .profile-wrap{margin:0 .3rem}.sidebar-closed .profile{justify-content:flex-start!important}.nav-scrim{display:block;position:fixed;inset:0;z-index:20;border:0;border-radius:0;background:rgba(15,23,42,.4)}.topbar{min-height:60px;align-items:center;padding:.75rem 1rem .75rem 3.5rem}.top-actions{gap:.4rem}.global-search{width:auto;min-width:0;flex:1;font-size:.74rem}.approval-shortcut{font-size:.68rem;padding:.4rem .55rem}.top-actions .agent-status,.help{display:none}.content{padding:14px 12px}.auth-layout{padding:0}}@media(max-width:390px){.topbar{padding-left:3.4rem;gap:.4rem}.approval-shortcut{font-size:.63rem;padding:.38rem .45rem}}
</style>
